// Aggregate the raw funded AI-assisted opportunities into the three mart payloads.
// Reproduces the documented SOQL methodology exactly:
//   - headline / monthly: each opp counted once (Assisted_by__c is overwrite, not append)
//   - per-bot: INCLUDES('<value>') == membership test on the multipicklist string

const WHITELIST = [
  'Inbox Manager - AI', 'Marketing - EW', 'Marketing - MA', 'Marketing - AR',
  'Marketing - FT', 'Marketing - GS', 'Marketing - LP', 'Marketing - OC',
  'Marketing - JB', 'NYS Auto DNQ'
];

const NOTES = {
  'Inbox Manager - AI': 'Inbox Manager (all personas, aggregate)',
  'Marketing - EW': 'Emma Wilson \u2014 CONTAMINATED by Olivia hot-lead clone leftover; per-persona unreliable until n8n-2 fix',
  'Marketing - MA': 'Megan Anderson',
  'Marketing - AR': 'Anne Robinson',
  'Marketing - FT': 'Faith Thompson',
  'Marketing - GS': 'Gianna Scavina / Help & Info',
  'Marketing - LP': 'Lauren Parker / New Deals Bot',
  'Marketing - OC': 'Olivia',
  'Marketing - JB': 'Jasmine Bennett / Reactivation Bot',
  'NYS Auto DNQ': 'DND / Auto-DQ automation'
};

const round2 = (n) => Math.round(n * 100) / 100;
const rows = $input.all().map((i) => i.json);

let total = 0;
let deals = 0;
const byMonth = {};
const byBot = {};
for (const v of WHITELIST) byBot[v] = { amt: 0, cnt: 0 };

for (const r of rows) {
  const amt = Number(r.csbs__Commission_Amount__c);
  if (!Number.isFinite(amt)) continue;
  total += amt;
  deals += 1;

  const fd = r.csbs__Funded_Date__c;
  if (fd) {
    const ym = String(fd).slice(0, 7); // 'YYYY-MM'
    byMonth[ym] = byMonth[ym] || { amt: 0, cnt: 0 };
    byMonth[ym].amt += amt;
    byMonth[ym].cnt += 1;
  }

  const tags = String(r.Assisted_by__c || '').split(';').map((s) => s.trim());
  for (const v of WHITELIST) {
    if (tags.includes(v)) {
      byBot[v].amt += amt;
      byBot[v].cnt += 1;
    }
  }
}

const p_by_month = Object.keys(byMonth).sort().map((m) => ({
  payout_month: m,
  commission_amt: round2(byMonth[m].amt),
  distinct_opps: byMonth[m].cnt
}));

const p_by_bot = WHITELIST
  .filter((v) => byBot[v].cnt > 0)
  .map((v) => ({
    assisted_by_value: v,
    commission_amt: round2(byBot[v].amt),
    distinct_opps: byBot[v].cnt,
    note: NOTES[v] || null
  }))
  .sort((a, b) => b.commission_amt - a.commission_amt);

const p_kpis = [
  { metric: 'total_commission_influenced', value: round2(total) },
  { metric: 'funded_deals', value: deals },
  { metric: 'avg_commission_per_deal', value: deals ? round2(total / deals) : 0 },
  { metric: 'months_tracked', value: p_by_month.length }
];

return [{ json: { p_kpis, p_by_month, p_by_bot } }];
